window.CERMAT_FACTS=[{"id":"fact-001","category":"Čísla","title":"Dvojka je jediná sudá výjimka","text":"Číslo 2 je jediné sudé prvočíslo. Každé větší sudé číslo totiž kromě jedničky a sebe samého dělí také dvojka.","sourceUrl":"https://personal.soton.ac.uk/jhr/math1001/chapter-primes.html","sourceTitle":"University of Southampton · Prime Numbers"},{"id":"fact-002","category":"Čísla","title":"Jednička není prvočíslo","text":"Prvočíslo má právě dva kladné dělitele. Jednička má pouze jediný, a proto do této skupiny nepatří.","sourceUrl":"https://personal.soton.ac.uk/jhr/math1001/chapter-primes.html","sourceTitle":"University of Southampton · Prime Numbers"},{"id":"fact-003","category":"Čísla","title":"Prvočísel nikdy nedojde","text":"Žádný seznam prvočísel nemůže být úplný, pokud je konečný. Eukleidova myšlenka s násobením a přičtením jedničky ukazuje, jak dokázat existenci dalších.","sourceUrl":"https://math.hmc.edu/funfacts/how-many-primes/","sourceTitle":"Harvey Mudd College · How many Primes?"},{"id":"fact-004","category":"Čísla","title":"Čísla mají prvočíselné stavebnice","text":"Každé celé číslo větší než 1 lze rozložit na součin prvočísel. Tento rozklad je až na pořadí činitelů jediný, například 60 = 2 · 2 · 3 · 5.","sourceUrl":"https://personal.soton.ac.uk/jhr/math1001/chapter-primes.html","sourceTitle":"University of Southampton · Prime Numbers"},{"id":"fact-005","category":"Matematické vzory","title":"Lichá čísla skládají čtverce","text":"Součet prvních n kladných lichých čísel je n². Například 1 + 3 + 5 + 7 = 16; každý další lichý počet teček přidá čtverci nový okraj.","sourceUrl":"https://nrich.maths.org/problems/picturing-square-numbers","sourceTitle":"University of Cambridge · NRICH"},{"id":"fact-006","category":"Matematické vzory","title":"Dva trojúhelníky vytvoří obdélník","text":"Tečky v řadách 1, 2, 3, …, n tvoří trojúhelníkové číslo. Dvě stejné takové sestavy se složí do obdélníku n × (n + 1).","sourceUrl":"https://nrich.maths.org/problems/triangles-within-squares","sourceTitle":"University of Cambridge · NRICH"},{"id":"fact-007","category":"Počítání","title":"Sto čísel sečteš pomocí dvojic","text":"Součet 1 + 2 + … + 100 je 5 050. Spáruj 1 se 100, 2 s 99 a tak dále: dostaneš 50 dvojic, z nichž každá má součet 101.","sourceUrl":"https://tasks.illustrativemathematics.org/content-standards/HSF/LE/A/tasks/1830","sourceTitle":"Illustrative Mathematics · Sum of the First n Natural Numbers"},{"id":"fact-008","category":"Matematické vzory","title":"Čtverce rostou po lichých krocích","text":"Rozdíl dvou sousedních čtvercových čísel je lichý: 6² − 5² = 11. Obecně platí (n + 1)² − n² = 2n + 1.","sourceUrl":"https://nrich.maths.org/problems/picturing-square-numbers","sourceTitle":"University of Cambridge · NRICH"},{"id":"fact-009","category":"Matematické vzory","title":"Součet krychlí je čtverec","text":"Platí 1³ + 2³ + … + n³ = (1 + 2 + … + n)². Pro n = 3 například dostaneme 1 + 8 + 27 = 36.","sourceUrl":"https://math.hmc.edu/funfacts/sum-of-cubes/","sourceTitle":"Harvey Mudd College · Sum of Cubes"},{"id":"fact-010","category":"Čísla","title":"Odmocnina ze dvou není zlomek","text":"√2 nelze přesně vyjádřit podílem dvou celých čísel. Klasický důkaz předpokládá zlomek v základním tvaru a ukáže, že by jeho čitatel i jmenovatel musely být sudé.","sourceUrl":"https://math.hmc.edu/funfacts/square-root-of-two-is-irrational/","sourceTitle":"Harvey Mudd College · Square Root of Two is Irrational"},{"id":"fact-011","category":"Paradoxy","title":"0,999… je přesně jedna","text":"Nekonečný desetinný zápis 0,999… označuje stejné číslo jako 1. Nejde o zaokrouhlení: součet 9/10 + 9/100 + 9/1000 + … je přesně jedna.","sourceUrl":"https://math.hmc.edu/funfacts/why-does-0-999-1/","sourceTitle":"Harvey Mudd College · Why Does 0.999… = 1?"},{"id":"fact-012","category":"Čísla","title":"Jedno číslo může mít dva zápisy","text":"Číslo 0,35 lze zapsat také jako 0,34999… s nekonečně mnoha devítkami. Jde o dva různé desetinné zápisy téže hodnoty.","sourceUrl":"https://math.hmc.edu/funfacts/why-does-0-999-1/","sourceTitle":"Harvey Mudd College · Why Does 0.999… = 1?"},{"id":"fact-013","category":"Geometrie","title":"Trojice 3, 4, 5 tvoří pravý úhel","text":"Trojúhelník se stranami 3, 4 a 5 je pravoúhlý, protože 3² + 4² = 5². Stejný tvar získáš například i ze stran 6, 8 a 10.","sourceUrl":"https://math.hmc.edu/funfacts/pythagorean-triples/","sourceTitle":"Harvey Mudd College · Pythagorean Triples"},{"id":"fact-014","category":"Geometrie","title":"Pythagorejských trojic je více","text":"Také délky 5, 12 a 13 dávají pravoúhlý trojúhelník: 25 + 144 = 169. Celá čísla ve stranách tedy nejsou výsadou známé trojice 3, 4, 5.","sourceUrl":"https://math.hmc.edu/funfacts/pythagorean-triples/","sourceTitle":"Harvey Mudd College · Pythagorean Triples"},{"id":"fact-015","category":"Geometrie","title":"Pravoúhlé trojúhelníky lze vyrábět vzorcem","text":"Pro celá čísla m > n > 0 tvoří délky m² − n², 2mn a m² + n² pravoúhlý trojúhelník. Například m = 4 a n = 1 dávají strany 15, 8 a 17.","sourceUrl":"https://math.hmc.edu/funfacts/pythagorean-triples/","sourceTitle":"Harvey Mudd College · Pythagorean Triples"},{"id":"fact-016","category":"Počítání","title":"Druhá mocnina čísla končícího pětkou","text":"U čísla 35 vynásob 3 následujícím číslem 4 a připoj 25: 35² = 1 225. Stejný postup funguje pro všechna kladná celá čísla končící číslicí 5.","sourceUrl":"https://math.hmc.edu/funfacts/squares-ending-in-5/","sourceTitle":"Harvey Mudd College · Squares Ending in 5"},{"id":"fact-017","category":"Počítání","title":"Násobení jedenácti využívá sousední číslice","text":"Při násobení 23 · 11 můžeš mezi 2 a 3 vložit jejich součet: 253. U větších součtů nezapomeň na přenos do dalšího řádu, například 57 · 11 = 627.","sourceUrl":"https://math.hmc.edu/funfacts/multiplication-by-11/","sourceTitle":"Harvey Mudd College · Multiplication by 11"},{"id":"fact-018","category":"Počítání","title":"Algebra pomůže počítat z hlavy","text":"Součin 98 · 102 je (100 − 2)(100 + 2) = 100² − 2² = 9 996. Vzorec pro rozdíl čtverců tak zrychlí i obyčejné násobení.","sourceUrl":"https://math.hmc.edu/funfacts/difference-of-squares/","sourceTitle":"Harvey Mudd College · Difference of Squares"},{"id":"fact-019","category":"Čísla","title":"Jedenáctku prozradí střídání znamének","text":"Číslo je dělitelné 11, právě když je dělitelný 11 střídavý součet jeho číslic. U čísla 1 331 například vyjde 1 − 3 + 3 − 1 = 0.","sourceUrl":"https://math.hmc.edu/funfacts/divisibility-by-eleven/","sourceTitle":"Harvey Mudd College · Divisibility by Eleven"},{"id":"fact-020","category":"Matematické triky","title":"Číslo 1 089 se může objevit pokaždé","text":"Zvol trojciferné číslo s přísně klesajícími číslicemi. Odečti jeho obrácený zápis a k rozdílu přičti obrácený rozdíl. Například 532 − 235 = 297 a 297 + 792 = 1 089.","sourceUrl":"https://math.hmc.edu/funfacts/magic-1089/","sourceTitle":"Harvey Mudd College · Magic 1089"},{"id":"fact-021","category":"Logika","title":"Dvě chybějící políčka zmaří pokrytí šachovnice","text":"Šachovnici 8 × 8 bez dvou diagonálně protilehlých rohů nepokryješ dominovými dílky 1 × 2. Chybějící rohy mají stejnou barvu, ale každý dílek musí zakrýt po jednom políčku obou barev.","sourceUrl":"https://math.hmc.edu/funfacts/dominoes-on-a-chessboard-2/","sourceTitle":"Harvey Mudd College · Dominoes on a Chessboard"},{"id":"fact-022","category":"Logika","title":"Tři ponožky zaručí shodnou dvojici","text":"Pokud máš v zásuvce ponožky jen dvou barev, tři vytažené ponožky zaručí alespoň dvě stejné barvy. Je to jednoduchá ukázka přihrádkového neboli holubníkového principu.","sourceUrl":"https://math.hmc.edu/funfacts/pigeonhole-principle/","sourceTitle":"Harvey Mudd College · Pigeonhole Principle"},{"id":"fact-023","category":"Geometrie","title":"Pravidelných konvexních mnohostěnů je jen pět","text":"Čtyřstěn, krychle, osmistěn, dvanáctistěn a dvacetistěn jsou jediná konvexní tělesa tvořená shodnými pravidelnými mnohoúhelníky se stejným uspořádáním u každého vrcholu. Říká se jim platónská tělesa.","sourceUrl":"https://math.hmc.edu/funfacts/regular-solids/","sourceTitle":"Harvey Mudd College · Regular Solids"},{"id":"fact-024","category":"Geometrie","title":"Krychle skrývá Eulerovu dvojku","text":"U každého konvexního mnohostěnu platí V − H + S = 2, kde V značí vrcholy, H hrany a S stěny. U krychle vyjde 8 − 12 + 6 = 2.","sourceUrl":"https://math.hmc.edu/funfacts/euler-characteristic/","sourceTitle":"Harvey Mudd College · Euler Characteristic"},{"id":"fact-025","category":"Geometrie","title":"Na kouli může mít trojúhelník tři pravé úhly","text":"Spoj severní pól se dvěma body rovníku vzdálenými o čtvrtinu obvodu a přidej kratší rovníkový oblouk. Tento kulový trojúhelník má tři pravé úhly; pravidlo 180° patří trojúhelníkům v rovině.","sourceUrl":"https://math.hmc.edu/funfacts/spherical-geometry/","sourceTitle":"Harvey Mudd College · Spherical Geometry"},{"id":"fact-026","category":"Matematické vzory","title":"Pascalův trojúhelník vzniká sčítáním","text":"Na okrajích Pascalova trojúhelníku stojí jedničky. Každé vnitřní číslo je součtem dvou čísel přímo nad ním, takže řadu 1, 3, 3, 1 vystřídá 1, 4, 6, 4, 1.","sourceUrl":"https://math.hmc.edu/funfacts/pascals-triangle-2/","sourceTitle":"Harvey Mudd College · Pascal’s Triangle"},{"id":"fact-027","category":"Algebra","title":"Trojúhelník čísel zná mocniny závorek","text":"Řádky Pascalova trojúhelníku obsahují koeficienty rozvoje (a + b)ⁿ. Řádek 1, 2, 1 například odpovídá známému vzorci (a + b)² = a² + 2ab + b².","sourceUrl":"https://math.hmc.edu/funfacts/pascals-triangle-2/","sourceTitle":"Harvey Mudd College · Pascal’s Triangle"},{"id":"fact-028","category":"Pravděpodobnost","title":"Na společné narozeniny stačí překvapivě malá skupina","text":"Při modelu 365 stejně pravděpodobných dnů a nezávislých narozenin překročí už ve skupině 23 lidí pravděpodobnost shody 50 %. Porovnávají se totiž všechny dvojice lidí.","sourceUrl":"https://nrich.maths.org/problems/same-number","sourceTitle":"University of Cambridge · NRICH"},{"id":"fact-029","category":"Paradoxy","title":"U tří dveří se vyplatí změnit volbu","text":"V klasické Monty Hallově úloze zvýší změna dveří šanci na výhru z 1/3 na 2/3. Platí to, když moderátor zná výhru, vždy otevře nevýherní nevybrané dveře a vždy nabídne změnu.","sourceUrl":"https://math.hmc.edu/funfacts/monty-hall-problem/","sourceTitle":"Harvey Mudd College · Monty Hall Problem"},{"id":"fact-030","category":"Paradoxy","title":"Souhrnná statistika může obrátit výsledek","text":"Simpsonův paradox nastane, když se vztah pozorovaný ve skupinách po jejich spojení obrátí. Důvodem mohou být rozdílné velikosti skupin, takže samotná procenta bez počtů mohou mást.","sourceUrl":"https://plus.maths.org/comment/8578","sourceTitle":"University of Cambridge · Plus, Simpson’s paradox"},{"id":"fact-031","category":"Nekonečno","title":"Sudých čísel je stejně mnoho jako kladných celých","text":"Každému kladnému celému číslu n přiřaď číslo 2n. Dostaneš párování bez vynechání a bez opakování, přestože sudá čísla tvoří jen část kladných celých čísel.","sourceUrl":"https://nrich.maths.org/articles/all-about-infinity","sourceTitle":"University of Cambridge · NRICH"},{"id":"fact-032","category":"Paradoxy","title":"Plný nekonečný hotel přijme dalšího hosta","text":"V Hilbertově myšlenkovém hotelu se každý host přesune z pokoje n do pokoje n + 1. První pokoj se uvolní, přestože předtím byly všechny pokoje obsazené.","sourceUrl":"https://plus.maths.org/comment/12348","sourceTitle":"University of Cambridge · Plus, Hilbert’s hotel"},{"id":"fact-033","category":"Nekonečno","title":"Hotel může uvolnit nekonečně mnoho pokojů","text":"Když se v Hilbertově hotelu každý host přesune z pokoje n do pokoje 2n, uvolní se všechny liché pokoje. I plný hotel tak přijme další spočetně nekonečnou řadu hostů.","sourceUrl":"https://plus.maths.org/comment/12348","sourceTitle":"University of Cambridge · Plus, Hilbert’s hotel"},{"id":"fact-034","category":"Geometrie","title":"Möbiův pásek má jedinou stranu","text":"Papírový proužek před slepením konců otoč o půl otáčky. Po vzniklém Möbiově pásku lze přejít na původní rub bez překročení okraje: jeho povrch je jednostranný.","sourceUrl":"https://www.physics.wisc.edu/ingersollmuseum/exhibits/mechanics/mobiusstrip/","sourceTitle":"University of Wisconsin–Madison · Ingersoll Museum"},{"id":"fact-035","category":"Historie symbolů","title":"Rovnítko se objevilo v tisku roku 1557","text":"Robert Recorde použil v knize The Whetstone of Witte dvě rovnoběžné čárky jako znak rovnosti. Jeho tehdejší rovnítko bylo delší než to, které píšeme dnes.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Miller/mathsym/relation/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-036","category":"Historie symbolů","title":"Plus a minus sloužily také obchodníkům","text":"V tištěné početnici Johannese Widmanna z roku 1489 značily + a − obchodní přebytky a nedostatky. Jejich příběh tak začíná jinak než dnešní školní sčítání a odčítání.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Miller/mathsym/operation/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-037","category":"Historie symbolů","title":"Odmocnítko kdysi nemělo horní čáru","text":"Znak podobný dnešnímu √ použil Christoff Rudolff v knize Die Coss roku 1525. Horní vodorovná čára, kterou dnes vyznačujeme celý odmocňovaný výraz, tehdy chyběla.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Miller/mathsym/operation/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-038","category":"Historie symbolů","title":"Čáru nad odmocněncem používal Descartes","text":"René Descartes v roce 1637 spojil odmocnítko s vodorovnou čárou nad odmocňovaným výrazem. Takový zápis usnadňuje poznat, která část příkladu patří pod odmocninu.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Miller/mathsym/operation/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-039","category":"Historie symbolů","title":"Znak nekonečna zavedl John Wallis","text":"Symbol ∞ se u Johna Wallise objevil roku 1655. Dnes nás upozorňuje na nekonečno, s nímž ale nelze bez rozmyslu počítat jako s běžným konečným číslem.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Miller/mathsym/calculus/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-040","category":"Historie symbolů","title":"Písmeno π je mladší než výpočty kruhu","text":"William Jones použil π pro poměr obvodu kružnice k jejímu průměru roku 1706. Matematici tento poměr zkoumali už ve starověku, dlouho před ustálením dnešního označení.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Biographies/Jones/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-041","category":"Historie počítání","title":"Desetinné zlomky mají dlouhou historii","text":"Simon Stevin pomohl v Evropě rozšířit počítání s desetinnými zlomky spisem z roku 1585. Nebyl jejich prvním objevitelem; dříve se používaly také v arabské a čínské matematice.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Biographies/Stevin/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-042","category":"Historie matematiky","title":"Algoritmus nese jméno matematika","text":"Slovo algoritmus vzniklo z latinské podoby jména al-Chvárizmího. Dnes označuje přesný postup řešení, například písemné dělení nebo postup počítačového programu.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Biographies/Al-Khwarizmi/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-043","category":"Historie matematiky","title":"Algebra dostala jméno z názvu knihy","text":"Slovo algebra souvisí s výrazem al-džabr v názvu al-Chvárizmího spisu o řešení rovnic. Jeho výklady byly psány slovy, bez dnešních písmen a symbolického zápisu.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Biographies/Al-Khwarizmi/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-044","category":"Matematici","title":"Fibonacci pomáhal šířit dnešní způsob počítání","text":"Leonardo z Pisy, známý jako Fibonacci, napsal roku 1202 Liber abaci. V Evropě tím pomáhal prosazovat indicko-arabské číslice a poziční desetinný zápis místo složitějších dobových postupů.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Biographies/Fibonacci/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-045","category":"Matematické vzory","title":"Fibonacciho posloupnost začíná sčítáním","text":"V posloupnosti 1, 1, 2, 3, 5, 8, 13, … je každý další člen součtem předchozích dvou. Fibonacci ji popsal při modelové úloze o množení králíků, nikoli jako přesný model skutečné populace.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Biographies/Fibonacci/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-046","category":"Matematici","title":"Archimédés sevřel π mezi dva zlomky","text":"Archimédés pomocí vepsaných a opsaných mnohoúhelníků dokázal 223/71 < π < 22/7. Známý zlomek 22/7 je tedy užitečná aproximace, ne přesná hodnota π.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Biographies/Archimedes/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-047","category":"Matematici","title":"Gauss našel konstrukci sedmnáctiúhelníku","text":"Carl Friedrich Gauss v mládí ukázal, že pravidelný sedmnáctiúhelník lze sestrojit pravítkem bez měřítka a kružítkem. Konstrukce pravidelných mnohoúhelníků tak propojil s teorií čísel.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Biographies/Gauss/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-048","category":"Matematici","title":"Emmy Noether změnila pohled na algebru","text":"Emmy Noether patří k zásadním osobnostem moderní abstraktní algebry. Místo jednotlivých výpočtů zkoumala společné vlastnosti matematických struktur, například okruhů a jejich ideálů.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Biographies/Noether_Emmy/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-049","category":"Matematici","title":"Sofie Kovalevská přednášela ve Stockholmu","text":"Sofie Kovalevská začala ve Stockholmu učit roku 1884 a v témže roce získala mimořádnou profesuru. Významně přispěla k diferenciálním rovnicím i matematickému popisu pohybu těles.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Biographies/Kovalevskaya/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-050","category":"Česká matematika","title":"Eduard Čech propojoval výzkum a školu","text":"Český matematik Eduard Čech proslul prací v topologii a geometrii. Zároveň se věnoval vzdělávání učitelů, školním osnovám a matematickým učebnicím.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Biographies/Cech/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-051","category":"Česká matematika","title":"Bolzano zkoumal zvláštnosti nekonečna","text":"Pražský myslitel Bernard Bolzano ukazoval, že nekonečnou množinu lze někdy spárovat s její vlastní částí. Jeho Paradoxy nekonečna vyšly posmrtně roku 1851.","sourceUrl":"https://mathshistory.st-andrews.ac.uk/Biographies/Bolzano/","sourceTitle":"University of St Andrews · MacTutor"},{"id":"fact-052","category":"Komenský","title":"Svět v obrazech vyšel roku 1658","text":"Komenského Orbis sensualium pictus poprvé vytiskli v Norimberku roku 1658. Učebnice spojovala jazykové učení s poznáváním věcí prostřednictvím obrázků.","sourceUrl":"https://npmk.gov.cz/pro-media/tiskove-zpravy/uc-se-moudrym-byti-orbis-pictus-v-behu-veku","sourceTitle":"Národní pedagogické muzeum a knihovna J. A. Komenského"},{"id":"fact-053","category":"Komenský","title":"První Orbis byl dvojjazyčný","text":"První vydání Orbis pictus obsahovalo latinu a němčinu. Vedle učení slov tak nabízelo i přímé porovnání dvou jazyků.","sourceUrl":"https://komensky.mjakub.cz/orbis--idc343","sourceTitle":"Muzeum Jana Amose Komenského v Uherském Brodě"},{"id":"fact-054","category":"Komenský","title":"Čísla v obrázcích pomáhala učit slova","text":"Orbis pictus propojoval očíslované předměty na ilustraci s odpovídajícími slovy v textu. Žák tak mohl propojit výraz s konkrétní věcí místo pouhého memorování seznamu.","sourceUrl":"https://komensky.mjakub.cz/orbis--idc343","sourceTitle":"Muzeum Jana Amose Komenského v Uherském Brodě"},{"id":"fact-055","category":"Komenský","title":"Škola hrou měla i divadelní podobu","text":"Schola ludus je Komenského soubor osmi školních her. Žáci při vystupování procvičovali latinu a učivo z jeho jazykové učebnice; nešlo jen o dnešní heslo pro zábavné vyučování.","sourceUrl":"https://komensky.mjakub.cz/schola-ludus-idc387","sourceTitle":"Muzeum Jana Amose Komenského v Uherském Brodě"},{"id":"fact-056","category":"Komenský","title":"Učení podle Komenského začínalo už doma","text":"Informatorium školy mateřské se věnovalo výchově malých dětí v rodině před začátkem školní docházky. Komenský v něm doporučoval také hry, pohyb a pozorování okolí.","sourceUrl":"https://komensky.mjakub.cz/informatorium-skoly-materske--idc288","sourceTitle":"Muzeum Jana Amose Komenského v Uherském Brodě"},{"id":"fact-057","category":"Komenský","title":"Komenský vytvořil i mapu Moravy","text":"Jeho mapa Moravy vyšla v Amsterdamu roku 1627. Při její přípravě využíval vlastní znalost krajiny i informace dalších lidí, aby zpřesnil starší místopisné údaje.","sourceUrl":"https://komensky.mjakub.cz/mapa-moravy-idc326","sourceTitle":"Muzeum Jana Amose Komenského v Uherském Brodě"},{"id":"fact-058","category":"Komenský","title":"Historická mapa ukazovala také hospodářství","text":"Komenského mapa Moravy neobsahovala jen sídla a přírodní prvky. Zaznamenávala i doly, sklárny, vinice nebo léčivé prameny, a pomáhala tak poznávat život v krajině.","sourceUrl":"https://komensky.mjakub.cz/mapa-moravy-idc326","sourceTitle":"Muzeum Jana Amose Komenského v Uherském Brodě"},{"id":"fact-059","category":"Komenský","title":"Brána jazyků otevřená předcházela Orbisu","text":"Komenského Janua linguarum reserata poprvé vyšla v Lešně roku 1631. Spojovala osvojování jazyka se základními poznatky o světě, nikoli pouze s izolovanými slovíčky.","sourceUrl":"https://komensky.mjakub.cz/janua-lingvarum--idc293","sourceTitle":"Muzeum Jana Amose Komenského v Uherském Brodě"},{"id":"fact-060","category":"Komenský","title":"Tisíc vět tvořilo promyšlenou učebnici","text":"Brána jazyků otevřená uspořádala látku do sta oddílů a tisíce vět. Pevná struktura měla pomáhat soustavnému poznávání jazyka i základů věd a dovedností.","sourceUrl":"https://komensky.mjakub.cz/janua-lingvarum--idc293","sourceTitle":"Muzeum Jana Amose Komenského v Uherském Brodě"},{"id":"fact-061","category":"Komenský","title":"Komenského narozeniny připomíná březen","text":"Jan Amos Komenský se narodil 28. března 1592 na Moravě. Jeho život zasáhla třicetiletá válka a proměny evropského školství, k nimž sám přispíval svými spisy.","sourceUrl":"https://komensky.knihovny.cz/zivotopis.html","sourceTitle":"Knihovny.cz · Jan Amos Komenský"},{"id":"fact-062","category":"Komenský","title":"Velkou část života strávil v exilu","text":"Komenský odešel roku 1628 do polského Lešna. Jeho život a práce pak pokračovaly v několika evropských zemích, takže jeho vzdělávací myšlenky překračovaly hranice českých zemí.","sourceUrl":"https://komensky.knihovny.cz/zivotopis.html","sourceTitle":"Knihovny.cz · Jan Amos Komenský"},{"id":"fact-063","category":"Komenský","title":"Požár připravil Komenského o knihy","text":"Při požáru Lešna v roce 1656 shořela velká část Komenského knihovny. Jeho práce tak poznamenaly nejen přesuny mezi zeměmi, ale i ztráta cenných podkladů.","sourceUrl":"https://komensky.knihovny.cz/zivotopis.html","sourceTitle":"Knihovny.cz · Jan Amos Komenský"},{"id":"fact-064","category":"Komenský","title":"Závěr života prožil v Nizozemí","text":"Po roce 1656 působil Komenský v Nizozemí, kde také roku 1670 zemřel. Jeho odkaz proto dodnes spojuje české země s nizozemským prostředím.","sourceUrl":"https://komensky.knihovny.cz/zivotopis.html","sourceTitle":"Knihovny.cz · Jan Amos Komenský"},{"id":"fact-065","category":"Komenský","title":"Komenského hrob najdeš v Naardenu","text":"Komenský je pochován v nizozemském Naardenu. Jeho hrob se nachází v kapli upravené na mauzoleum, vedle něhož působí muzeum věnované jeho životu a dílu.","sourceUrl":"https://mzv.gov.cz/hague/en/bilateral_relations/comenius_museum_and_mausoleum_in_naarden.html","sourceTitle":"Ministerstvo zahraničních věcí ČR · Velvyslanectví v Haagu"},{"id":"fact-066","category":"České školství","title":"Den učitelů souvisí s Komenským","text":"Český Den učitelů připadá na 28. března, výročí Komenského narození. Připomíná práci učitelů i dlouhou tradici uvažování o tom, jak se lidé nejlépe učí.","sourceUrl":"https://npmk.gov.cz/novinky/npmk/den-ucitelu-privedl-do-npmk-stovky-navstevniku","sourceTitle":"Národní pedagogické muzeum a knihovna J. A. Komenského"},{"id":"fact-067","category":"České školství","title":"Pražská univerzita vznikla roku 1348","text":"Karel IV. založil univerzitu listinou ze 7. dubna 1348. Od počátku měla čtyři fakulty: svobodných umění, lékařskou, právnickou a teologickou.","sourceUrl":"https://cuni.cz/UK-103.html","sourceTitle":"Univerzita Karlova · Historie v datech"},{"id":"fact-068","category":"České školství","title":"Školství výrazně změnil řád z roku 1774","text":"Všeobecný školní řád Marie Terezie z 6. prosince 1774 stanovil všeobecnou vyučovací povinnost. Současně sjednocoval pravidla pro školy, učitele a dohled nad výukou.","sourceUrl":"https://npmk.gov.cz/novinky/muzeum-npmk/skolni-rad-po-250-letech","sourceTitle":"Národní pedagogické muzeum a knihovna J. A. Komenského"},{"id":"fact-069","category":"České školství","title":"Staré základní školství mělo tři typy škol","text":"Školní řád z roku 1774 rozlišoval školy triviální, hlavní a normální. Nešlo tedy o dnešní jednotnou soustavu základních škol, ale o různé úrovně a úkoly škol.","sourceUrl":"https://npmk.gov.cz/novinky/muzeum-npmk/skolni-rad-po-250-letech","sourceTitle":"Národní pedagogické muzeum a knihovna J. A. Komenského"},{"id":"fact-070","category":"Matematici","title":"Sedm mostů dalo vzniknout novému pohledu","text":"Leonhard Euler ukázal, že tehdejších sedm mostů v Královci nelze projít tak, aby každý přešel právě jednou. Pro řešení bylo důležité spojení míst, nikoli přesné délky mostů.","sourceUrl":"https://scholarlycommons.pacific.edu/euler-works/53/","sourceTitle":"University of the Pacific · Euler Archive, E053"}];
